def main(argv):
    try:
        if len(argv) != 2 or argv[1] not in ("run", "record", "replay"):
            fail(EXIT_INPUT, "INPUT")
        raw = sys.stdin.buffer.read()
        if argv[1] == "run":
            exit_code, out, err = execute(raw)
        elif argv[1] == "record":
            # 底层成败均退出 0、stderr 为空，stdout 输出记录。
            exit_code, out, err = 0, build_record(raw), b""
